definition.script:
pipeline {
    agent {
        label 'build'
    }
    tools {
        maven 'maven'
        jdk 'jdk'
    }

    parameters {
        string defaultValue: '{{ BRANCH_NAME }}', description: '分支名称', name: 'BRANCH'
        choice choices: ['false', 'true'], description: '重启服务', name: 'restart'
    }

    environment {
        def IMAGE_TAG = sh(script: 'date +%Y-%m-%d-%H-%M', returnStdout:true).trim()
        MAIN_CLASS = ""
        CLASSPATH = ""
        IMAGE_HARBOR = "{{ IMAGE_HARBOR }}"
        CODE_REPOSITORY = "{{ CODE_REPOSITORY }}"
        CONFIG_REPOSITORY = "{{ CONFIG_REPOSITORY }}"
        PROJECT_NAME = "{{ PROJECT_NAME }}"
        CONFIG_BRANCH = "{{ CONFIG_BRANCH }}"
        APP_NAME = "{{ APP_NAME }}"
        SERVICE_NAME = "{{ SERVICE_NAME }}"
        SERVICE_PORT = "{{ SERVICE_PORT }}"
        LIMIT_MEMORY = "{{ LIMIT_MEMORY }}"
        LIMIT_CPU = "{{ LIMIT_CPU }}"
        PRIORITY_CLASS_NAME = "{{ PRIORITY_CLASS_NAME }}"
        REQUESTS_MEMORY = "{{ REQUESTS_MEMORY }}"
        REQUESTS_CPU = "{{ REQUESTS_CPU }}"
        REPLICAS = {{ REPLICAS }}
        TARGET = "{{ TARGET }}"
        TIMEZONE = "{{ TIMEZONE }}"
        JAVA_OPTS = "{{ JAVA_OPTS }}"
        def IS_JOB = sh(script: 'echo "{{ APP_NAME }}" |awk -F \'-\' \'{print $NF}\'', returnStdout:true).trim()
    }

    stages {
        stage('清理工作空间') {
            when {
                allOf {
                    environment name: 'restart', value: 'false'
                }
            }
            steps {
                deleteDir()
            }
        }

        stage('克隆代码仓库') {
            when {
                allOf {
                    environment name: 'restart', value: 'false'
                }
            }
            steps {
                checkout([$class: 'GitSCM', branches: [[name: "*/${BRANCH}"]], extensions: [], userRemoteConfigs: [[credentialsId: 'jenkins', url: "${CODE_REPOSITORY}"]]])
            }
        }

        stage('编译打包') {
            when {
                allOf {
                    environment name: 'restart', value: 'false'
                }
            }
            steps {
                sh 'mvn clean package -Dmaven.test.skip=true'
            }
        }

        stage('克隆配置仓库') {
            when {
                allOf {
                    environment name: 'restart', value: 'false'
                }
            }
            steps {
                checkout([$class: 'GitSCM', branches: [[name: "*/${CONFIG_BRANCH}"]], extensions: [[$class: 'RelativeTargetDirectory', relativeTargetDir: 'configs']], userRemoteConfigs: [[credentialsId: 'jenkins', url: "${CONFIG_REPOSITORY}"]]])
            }
        }

        stage('构建镜像并上传到Harbor仓库') {
            when {
                allOf {
                    environment name: 'restart', value: 'false'
                }
            }
            steps {
                sh """
                	if [ "${TARGET}" = "contract-option-cycle-market-provider/target/contract-option-new-market-provider" ]; then
                		mv ${TARGET} configs/ ; mv configs/contract-option-new-market-provider configs/	contract-option-cycle-market-provider
            		else
                		mv ${TARGET} configs/
                	fi
                """

                dir('configs/') {
                    script {
                        if ( env.IS_JOB == "job" ) {
                            if (env.APP_NAME == "report-day-sum-job") {
                                docker.withRegistry("https://${IMAGE_HARBOR}", "docker-registry") {
                                    echo "IMAGE_TAG: $IMAGE_TAG"
                                	def App = docker.build("${IMAGE_HARBOR}/${PROJECT_NAME}/${APP_NAME}:${IMAGE_TAG}", "-f Dockerfile --build-arg JAVA_OPTS='${JAVA_OPTS}' --build-arg APP_NAME='report-day-sum' .")
                                	App.push()
                            	}
                            	sh 'docker rmi ${IMAGE_HARBOR}/${PROJECT_NAME}/${APP_NAME}:${IMAGE_TAG}'
                        	} else {
                            	docker.withRegistry("https://${IMAGE_HARBOR}", "docker-registry") {
                                	echo "IMAGE_TAG: $IMAGE_TAG"
                            		def App = docker.build("${IMAGE_HARBOR}/${PROJECT_NAME}/${APP_NAME}:${IMAGE_TAG}", "-f Dockerfile --build-arg JAVA_OPTS='${JAVA_OPTS}' --build-arg APP_NAME='${APP_NAME}' .")
                            		App.push()
                        		}
                        		sh 'docker rmi ${IMAGE_HARBOR}/${PROJECT_NAME}/${APP_NAME}:${IMAGE_TAG}'
                    		}
                		} else {
                    		docker.withRegistry("https://${IMAGE_HARBOR}", 'docker-registry') {
                        		def MAIN_CLASS = sh(script: 'cat ${APP_NAME}/bin/start.sh | grep MAIN_CLASS= |awk -F = \'{print $2}\'', returnStdout:true).trim()
                    			def CLASSPATH = sh(script: 'echo "/usr/local/apps/${APP_NAME}/classes:/usr/local/apps/${APP_NAME}/lib/*"', returnStdout:true).trim()
                    			echo "IMAGE_TAG: $IMAGE_TAG"
                    			echo "MAIN_CLASS: $MAIN_CLASS"
                    			echo "CLASSPATH: $CLASSPATH"
                    			def App = docker.build("${IMAGE_HARBOR}/${PROJECT_NAME}/${APP_NAME}:${IMAGE_TAG}", "-f Dockerfile --build-arg JAVA_OPTS='${JAVA_OPTS}' --build-arg APP_NAME='${APP_NAME}' --build-arg CLASSPATH='${CLASSPATH}' --build-arg MAIN_CLASS='${MAIN_CLASS}' .")
                    			App.push()
                			}

                			sh 'docker rmi ${IMAGE_HARBOR}/${PROJECT_NAME}/${APP_NAME}:${IMAGE_TAG}'
            			}
        			}
                }

            }
        }

        stage('部署到kubernetes集群中') {
            when {
                allOf {
                    environment name: 'restart', value: 'false'
                }
            }
            steps {
                withKubeConfig(credentialsId: '{{ KUBE_CONFIG }}') {
                    sh '''
                    	cd configs/apps-chart
                    	sed -i -e "s#__NAME__#$APP_NAME#g" \
                    	    -e "s#__PROJECT_NAME__#$PROJECT_NAME#g" \
                    	    -e "s#__TAG__#$IMAGE_TAG#g" \
                    	    -e "s#__LIMIT_MEMORY__#$LIMIT_MEMORY#g" \
                    	    -e "s#__REQUESTS_MEMORY__#$REQUESTS_MEMORY#g" \
                    	    -e "s#__SERVICE_NAME__#$SERVICE_NAME#g" \
                    	    -e "s#__PORT__#$SERVICE_PORT#g" \
                    	    -e "s#__REQUESTS_CPU__#$REQUESTS_CPU#g" \
                    	    -e "s#__LIMIT_CPU__#$LIMIT_CPU#g" \
                    	    -e "s#__REPLICAS__#$REPLICAS#g" \
                    	    -e "s#__PRIORITY_CLASS_NAME__#$PRIORITY_CLASS_NAME#g" \
                    	    -e "s#__TZ__#$TIMEZONE#" values.yaml
                    	helm template . > apps.yaml
                    	cat apps.yaml
                    	kubectl apply -f apps.yaml
                    '''
                }
            }
        }

        stage('重启Pod') {
            when {
                allOf {
                    environment name: 'restart', value: 'true'
                }

            }
            steps {
                withKubeConfig(credentialsId: '{{ KUBE_CONFIG }}') {
                    sh '''
                    	kubectl rollout restart deployment/${APP_NAME} -n apps
                    '''
                }
            }
        }
    }

}
